import type { CommissionInput } from '../commission'

/**
 * A hypothetical change on top of the real data (D-021). Never written back to the real data.
 * `legExtras[i]` belongs to `input.teamVolumes[i]` (the UI maps indices to leg IDs and names).
 */
export interface Scenario {
  /** Extra own customer turnover. */
  readonly ownExtra: number
  /** Extra points per leg, generated by each leg's direct partner (generation 1). */
  readonly legExtras: readonly number[]
}

const sum = (values: readonly number[]) => values.reduce((total, value) => total + value, 0)

export function teamExtraOf(scenario: Scenario): number {
  return Math.round(sum(scenario.legExtras) * 100) / 100
}

/**
 * Hypothetical engine input: own CT + `ownExtra`; each leg's extra points are added to that
 * leg's VE and, once, to generation 1 (they are its direct partner's own points). Nothing is
 * inferred for deeper generations. The engine then recomputes TT, the order of the legs
 * (a weak leg may become the strongest), TT-1/2/3, the level and the commission.
 */
export function applyScenario(input: CommissionInput, scenario: Scenario): CommissionInput {
  if (scenario.legExtras.length > input.teamVolumes.length) throw new Error('More leg extras than legs')
  const [generation1 = 0, ...deeper] = input.generationVolumes
  return {
    ...input,
    customerTurnover: input.customerTurnover + scenario.ownExtra,
    generationVolumes: [generation1 + sum(scenario.legExtras), ...deeper],
    teamVolumes: input.teamVolumes.map((volume, index) => volume + (scenario.legExtras[index] ?? 0)),
  }
}
